// Gameboy カラーパレット定義
// パレット初期化関数
void dot_landscape_palette_init(RetroColorPalette& palette) {
    palette.setColor(0, 0x0000); // 透明色
    palette.setColor(1, 0x9DE1); // RGB(155,188,15)
    palette.setColor(2, 0x8D61); // RGB(139,172,15)
    palette.setColor(3, 0x7CE1); // RGB(123,156,15)
    palette.setColor(4, 0x6C61); // RGB(107,140,15)
    palette.setColor(5, 0x5BE1); // RGB(91,124,15)
    palette.setColor(6, 0x4B61); // RGB(75,108,15)
    palette.setColor(7, 0x3AE1); // RGB(59,92,15)
    palette.setColor(8, 0x2A61); // RGB(43,76,15)
    palette.setColor(9, 0x19E1); // RGB(27,60,15)
    palette.setColor(10, 0x09C1); // RGB(15,56,15)
    palette.setColor(11, 0x0140); // RGB(0,40,0)
    palette.setColor(12, 0x0100); // RGB(0,32,0)
    palette.setColor(13, 0x00C0); // RGB(0,24,0)
    palette.setColor(14, 0x0080); // RGB(0,16,0)
    palette.setColor(15, 0x0040); // RGB(0,8,0)
}

